// Resolve the CSV resource URL from the NESO datapackage response.
// The datapackage exposes a `resources` array; we want the first CSV.
const pkg = $input.first().json;
const resources = (pkg?.result?.resources) || (pkg?.resources) || [];
const csv = resources.find(r => (r.format || '').toLowerCase() === 'csv') || resources[0];
if (!csv || !csv.path) {
  throw new Error('Could not resolve CSV resource from datapackage response');
}
return [{ json: { csv_url: csv.path, resolved_at: new Date().toISOString() } }];

// Parse the NESO TEC CSV into one item per row.
// NESO column names vary slightly between releases, so we map flexibly.
const raw = $input.first().json.data || $input.first().json;
const text = typeof raw === 'string' ? raw : (raw.body || '');
if (!text) throw new Error('Empty CSV body');

function parseCsv(s) {
  const rows = [];
  let i = 0, field = '', row = [], inQ = false;
  while (i < s.length) {
    const c = s[i];
    if (inQ) {
      if (c === '"' && s[i+1] === '"') { field += '"'; i += 2; continue; }
      if (c === '"') { inQ = false; i++; continue; }
      field += c; i++; continue;
    }
    if (c === '"') { inQ = true; i++; continue; }
    if (c === ',') { row.push(field); field = ''; i++; continue; }
    if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; i++; continue; }
    if (c === '\r') { i++; continue; }
    field += c; i++;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

const rows = parseCsv(text).filter(r => r.length > 1);
const header = rows.shift().map(h => h.trim());
const idx = (name) => header.findIndex(h => h.toLowerCase().replace(/[^a-z0-9]/g, '') === name.toLowerCase().replace(/[^a-z0-9]/g, ''));

const projectIdx = [idx('ProjectName'), idx('ProjectRef'), idx('CustomerName'), idx('GSP')].find(i => i >= 0);
const developerIdx = [idx('Customer'), idx('CustomerName'), idx('Company'), idx('Developer')].find(i => i >= 0);
const plantIdx = [idx('PlantType'), idx('Technology'), idx('PlantTypeRev')].find(i => i >= 0);
const mwIdx = [idx('MWConnected'), idx('MW'), idx('MWeffective'), idx('CapacityMW'), idx('GenerationCapacityMW')].find(i => i >= 0);
const connIdx = [idx('ConnectionDate'), idx('CompletionDate'), idx('AcceptedDate')].find(i => i >= 0);
const statusIdx = [idx('Status'), idx('ProjectStatus'), idx('ConnectionStatus')].find(i => i >= 0);

const pullDate = new Date().toISOString();
const out = [];
for (let r = 0; r < rows.length; r++) {
  const row = rows[r];
  if (!row.some(v => v && v.trim())) continue;
  const obj = Object.fromEntries(header.map((h, i) => [h, row[i] ?? '']));
  out.push({
    json: {
      pull_date: pullDate,
      project_id: (projectIdx >= 0 ? row[projectIdx] : `row-${r}`) || `row-${r}`,
      developer: developerIdx >= 0 ? row[developerIdx] : null,
      plant_type: plantIdx >= 0 ? row[plantIdx] : null,
      mw: mwIdx >= 0 ? Number(String(row[mwIdx]).replace(/[^0-9.-]/g, '')) || null : null,
      connection_date: connIdx >= 0 ? row[connIdx] : null,
      status: statusIdx >= 0 ? row[statusIdx] : null,
      raw: obj
    }
  });
}
return out;

// Stage 3: keep BESS rows whose connection_date falls in 2027-01-01..2035-12-31.
const BESS = /battery|storage|bess/i;
const from = new Date('2027-01-01').getTime();
const to   = new Date('2035-12-31').getTime();
return $input.all().filter(item => {
  const j = item.json;
  if (!BESS.test(j.plant_type || '')) return false;
  if (!j.connection_date) return false;
  const t = new Date(j.connection_date).getTime();
  return Number.isFinite(t) && t >= from && t <= to;
});

// Stage 3.5: cap enrichment to top 10 developers by MW per run.
// Constraint: keep Clay credit cost under $1/run.
const items = $input.all().slice();
items.sort((a, b) => (Number(b.json.mw) || 0) - (Number(a.json.mw) || 0));
return items.slice(0, 10);

// Stage 5: keyword-only confirmation scoring. No LLM.
//   +1 per keyword hit per source
//   +2 per TED tender hit
//   +1 per news hit
const KEYWORDS = [
  'BESS', 'battery storage', 'MWh', 'construction', 'groundbreaking',
  'commissioning', 'energization', 'grid connection', 'planning permission'
];

const pair = $input.all();
const tedRaw  = pair[0]?.json || {};
const newsRaw = pair[1]?.json || {};

const dev = (tedRaw.developer || newsRaw.developer || $('Wait for Clay enriched').first().json.developer || '').toString();
const tedHits  = Array.isArray(tedRaw.notices) ? tedRaw.notices : (tedRaw.results || []);
const newsBody = typeof newsRaw === 'string' ? newsRaw : (newsRaw.data || newsRaw.body || '');

const sources = [];
let score = 0;

for (const t of tedHits) {
  const url = t.uri || t.url || t.publicationUri || '';
  const snippet = (t.title || t['title-proc'] || JSON.stringify(t)).toString().slice(0, 240);
  sources.push({ type: 'ted', url, snippet });
  score += 2;
  for (const kw of KEYWORDS) {
    if (snippet.toLowerCase().includes(kw.toLowerCase())) score += 1;
  }
}

const itemRe = /<item[\s\S]*?<\/item>/g;
const titleRe = /<title>([\s\S]*?)<\/title>/;
const linkRe  = /<link>([\s\S]*?)<\/link>/;
const items = (newsBody.match(itemRe) || []).slice(0, 5);
for (const it of items) {
  const title = (it.match(titleRe)?.[1] || '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
  const link  = (it.match(linkRe)?.[1] || '').trim();
  if (!title) continue;
  sources.push({ type: 'news', url: link, snippet: title });
  score += 1;
  for (const kw of KEYWORDS) {
    if (title.toLowerCase().includes(kw.toLowerCase())) score += 1;
  }
}

// Carry through enriched fields from the Wait callback.
const enriched = $('Wait for Clay enriched').first().json;

return [{
  json: {
    ...enriched,
    developer: dev || enriched.developer,
    confirmation_score: score,
    confirmation_sources: sources,
    ted_hits: tedHits.length,
    news_hits: items.length,
    other_tec_count: Number(enriched.other_tec_count || 0)
  }
}];

